import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 처리 구분 -> 변경될 예약 승인 상태
const NEXT_STATUS: Record<string, string> = {
  '승인': '승인',
  '반려': '반려',
  '승인취소': '승인취소',
  '삭제': '삭제',
  '취소': '취소',
};

// 처리 구분별로 허용되는 현재 상태
// 삭제는 전환표에 현재 상태 제한이 없어 이미 삭제된 건만 막는다 (가정)
const ALLOWED_FROM: Record<string, string[]> = {
  '승인': ['신청'],
  '반려': ['신청'],
  '승인취소': ['승인'],
  '취소': ['신청', '승인'],
  '삭제': ['신청', '승인', '반려', '승인취소', '취소'],
};

@Controller('api/v1')
export class FnSfr03305Controller {
  @Post('/resource-reservations/:resourceReservationId/process')
  @HttpCode(200)
  async processResourceReservation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자원 담당자', '임직원');
    const data = checks.inputOf(req.body);
    const reservationId = req.params['resourceReservationId'];
    const processType = data['processType'];
    if (typeof processType !== 'string' || NEXT_STATUS[processType] === undefined) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 구분을 확인해 주세요.');
    }
    const rejectReasonRaw = data['rejectReason'];
    if (rejectReasonRaw !== undefined && rejectReasonRaw !== null && typeof rejectReasonRaw !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '반려 사유 형식이 올바르지 않습니다.');
    }
    const rejectReason = typeof rejectReasonRaw === 'string' && rejectReasonRaw !== '' ? rejectReasonRaw : null;
    if (!/^[0-9]+$/.test(reservationId)) {
      throw new ApiError(404, 'RESERVATION_NOT_FOUND', '처리할 예약을 찾을 수 없습니다.');
    }
    // 승인·반려·승인취소·삭제는 자원 담당자만 할 수 있다 (취소는 예약자 본인)
    if (processType !== '취소') {
      user.require('자원 담당자');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT approval_status AS "approvalStatus", reserver_id AS "reserverId"
           FROM resource_reservation
          WHERE resource_reservation_id = CAST(:id AS bigint)
          FOR UPDATE`,
        { id: reservationId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'RESERVATION_NOT_FOUND', '처리할 예약을 찾을 수 없습니다.');
      }
      const current = found[0];
      if (!ALLOWED_FROM[processType].includes(current.approvalStatus)) {
        throw new ApiError(409, 'INVALID_RESERVATION_STATUS', '현재 상태에서는 할 수 없는 처리입니다.');
      }
      if (processType === '취소' && String(current.reserverId) !== String(user.id)) {
        throw new ApiError(403, 'FORBIDDEN', '예약자 본인만 취소할 수 있습니다.');
      }
      const rows = await db.query(
        `UPDATE resource_reservation
            SET approval_status = :nextStatus,
                reject_reason = CASE WHEN :processType = '반려' THEN CAST(:rejectReason AS text) ELSE reject_reason END,
                processor_id = CAST(:userId AS bigint),
                processed_at = now(),
                updated_at = now()
          WHERE resource_reservation_id = CAST(:id AS bigint)
        RETURNING resource_reservation_id AS "resourceReservationId",
                  approval_status AS "approvalStatus",
                  processed_at AS "processedAt"`,
        {
          nextStatus: NEXT_STATUS[processType],
          processType,
          rejectReason,
          userId: user.id,
          id: reservationId,
        },
      );
      return rows[0];
    });
  }
}

