import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Pager,
  RefName,
  Select,
  Table as _unused,
  TextInput,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;
const VIEW_TYPES: [string, string][] = [['일간', '일간'], ['주간', '주간'], ['월간', '월간']];

// 현재 상태별로 선택할 수 있는 처리 구분 (전환표)
function allowedTypes(status: unknown): string[] {
  if (status === '신청') return ['승인', '반려', '취소', '삭제'];
  if (status === '승인') return ['승인취소', '취소', '삭제'];
  if (status === '반려' || status === '승인취소' || status === '취소') return ['삭제'];
  return [];
}

export default function FnSfr03305Page({ role, notify }: PageProps) {
  const today = new Date().toISOString().slice(0, 10);
  const [viewType, setViewType] = useState('월간');
  const [baseDate, setBaseDate] = useState(today);
  const [resourceId, setResourceId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({ viewType: '월간', baseDate: today, resourceId: '' });
  const [pageNo, setPageNo] = useState(0);
  const [target, setTarget] = useState<Row | null>(null);
  const [processType, setProcessType] = useState('');
  const [rejectReason, setRejectReason] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/resource-reservations', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [applied, pageNo, role],
  );
  const rows = (data?.items ?? []).filter((r) => r['approvalStatus'] !== '삭제');
  const pending = rows.filter((r) => r['approvalStatus'] === '신청').length;

  function search() {
    setPageNo(0);
    setApplied({ viewType, baseDate, resourceId });
  }

  function reset() {
    setViewType('월간');
    setBaseDate(today);
    setResourceId('');
    setPageNo(0);
    setApplied({ viewType: '월간', baseDate: today, resourceId: '' });
  }

  function open(row: Row) {
    setTarget(row);
    setProcessType('');
    setRejectReason('');
  }

  async function submit() {
    if (!target) return;
    if (processType === '') {
      throw new Error('처리 구분을 선택해 주세요.');
    }
    const body: Row = { processType };
    if (processType === '반려' && rejectReason !== '') {
      body['rejectReason'] = rejectReason;
    }
    await call('POST', `/resource-reservations/${target['resourceReservationId']}/process`, role, body);
    notify('예약을 처리했습니다.');
    setTarget(null);
    reload();
  }

  const columns = [
    { key: 'resourceReservationId', label: '자원 예약 ID' },
    {
      key: 'resourceId',
      label: '자원',
      render: (r: Row) => <RefName table="resource" role={role} value={r['resourceId']} />,
    },
    { key: 'title', label: '예약 내용' },
    { key: 'startAt', label: '시작 일시', render: (r: Row) => <DateText value={r['startAt']} time /> },
    { key: 'endAt', label: '종료 일시', render: (r: Row) => <DateText value={r['endAt']} time /> },
    { key: 'approvalStatus', label: '예약 승인 상태', render: (r: Row) => <Badge value={r['approvalStatus']} /> },
    {
      key: 'action',
      label: '처리',
      render: (r: Row) =>
        allowedTypes(r['approvalStatus']).length > 0 ? (
          <button type="button" onClick={() => open(r)}>
            처리
          </button>
        ) : null,
    },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>승인 대기</h2>
        <Tiles items={[['신청 상태 예약', pending]]} />
      </section>
      <section className="box span-4">
        <h2>조회 예약</h2>
        <Tiles items={[['전체 건수', data?.total ?? 0]]} />
      </section>
      <section className="box span-12">
        <h2>예약 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="일간/주간/월간" required>
            <Select value={viewType} onChange={setViewType} options={VIEW_TYPES} />
          </Field>
          <Field label="조회 기준일" required>
            <DateInput value={baseDate} onChange={setBaseDate} />
          </Field>
          <Field label="자원">
            <LookupSelect table="resource" role={role} value={resourceId} onChange={setResourceId} />
          </Field>
        </Filters>
        <Band total={data?.total} />
        {error !== '' && <p>{error}</p>}
        <DataTable columns={columns} rows={rows} onRowClick={open} empty="예약이 없습니다." />
        <Pager page={pageNo} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      {target && (
        <Drawer title="예약 처리" onClose={() => setTarget(null)}>
          <Form onSubmit={submit} submit="처리">
            <Field label="예약 내용" wide>
              <span>{String(target['title'] ?? '')}</span>
            </Field>
            <Field label="예약 승인 상태">
              <Badge value={target['approvalStatus']} />
            </Field>
            <Field label="처리 구분(승인/반려/승인취소/삭제/취소)" required>
              <Select
                value={processType}
                onChange={setProcessType}
                options={allowedTypes(target['approvalStatus']).map((t): [string, string] => [t, t])}
              />
            </Field>
            {processType === '반려' && (
              <Field label="반려 사유" wide>
                <TextInput value={rejectReason} onChange={setRejectReason} multiline />
              </Field>
            )}
          </Form>
        </Drawer>
      )}
    </div>
  );
}
